-- ChinaGo West Africa commerce foundation (Togo launch)
create extension if not exists pgcrypto;
create table if not exists public.store_members (id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,member_role text not null default 'staff' check(member_role in ('owner','manager','catalog','orders','support')),created_at timestamptz not null default now(),unique(store_id,user_id));
create index if not exists store_members_user_idx on public.store_members(user_id,store_id);
create table if not exists public.store_settings (store_id uuid primary key references public.stores(id) on delete cascade,logo_url text,banner_url text,primary_color text not null default '#0B2D5B',accent_color text not null default '#FF8A00',currency text not null default 'XOF',country_code text not null default 'TG',contact_email text,contact_phone text,custom_domain text unique,checkout_enabled boolean not null default true,shipping_policy text,return_policy text,seo_title text,seo_description text,updated_at timestamptz not null default now());
create table if not exists public.wallet_accounts (id uuid primary key default gen_random_uuid(),owner_user_id uuid not null references auth.users(id) on delete restrict,store_id uuid references public.stores(id) on delete restrict,account_type text not null check(account_type in ('seller','dropshipper','supplier','cargo','platform')),currency text not null default 'XOF',status text not null default 'active' check(status in ('active','frozen','closed')),created_at timestamptz not null default now(),unique(owner_user_id,store_id,account_type,currency));
create index if not exists wallet_accounts_owner_idx on public.wallet_accounts(owner_user_id);
create table if not exists public.wallet_transactions (id uuid primary key default gen_random_uuid(),wallet_account_id uuid not null references public.wallet_accounts(id) on delete restrict,order_id uuid references public.orders(id) on delete set null,payment_transaction_id uuid references public.payment_transactions(id) on delete set null,entry_type text not null check(entry_type in ('sale_credit','commission_debit','refund_debit','payout_debit','payout_reversal','adjustment_credit','adjustment_debit','supplier_cost','cargo_cost')),amount numeric(18,2) not null check(amount>0),direction text not null check(direction in ('credit','debit')),currency text not null default 'XOF',description text,idempotency_key text not null unique,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create index if not exists wallet_transactions_account_date_idx on public.wallet_transactions(wallet_account_id,created_at desc);
create index if not exists wallet_transactions_order_idx on public.wallet_transactions(order_id);
create table if not exists public.payout_requests (id uuid primary key default gen_random_uuid(),wallet_account_id uuid not null references public.wallet_accounts(id) on delete restrict,user_id uuid not null references auth.users(id) on delete restrict,amount numeric(18,2) not null check(amount>0),currency text not null default 'XOF',payout_method text not null,beneficiary_name text not null,beneficiary_phone text,beneficiary_account text,beneficiary_bank text,provider text,provider_reference text,status text not null default 'requested' check(status in ('requested','under_review','approved','processing','paid','rejected','failed','cancelled')),admin_note text,requested_at timestamptz not null default now(),processed_at timestamptz);
create index if not exists payout_requests_user_date_idx on public.payout_requests(user_id,requested_at desc);
create index if not exists payout_requests_status_idx on public.payout_requests(status,requested_at);
create table if not exists public.payment_provider_configs (id uuid primary key default gen_random_uuid(),provider_code text not null,country_code text not null default 'TG',currency text not null default 'XOF',display_name text not null,payment_methods jsonb not null default '[]'::jsonb,mode text not null default 'test' check(mode in ('test','live')),is_enabled boolean not null default false,is_primary boolean not null default false,public_config jsonb not null default '{}'::jsonb,credential_status text not null default 'not_configured' check(credential_status in ('not_configured','test_configured','live_configured','verification_required')),updated_at timestamptz not null default now(),unique(provider_code,country_code));
insert into public.payment_provider_configs(provider_code,country_code,currency,display_name,payment_methods,is_enabled,is_primary,credential_status) values
('payoneer','TG','XOF','Payoneer','[{"code":"card","label":"Carte bancaire"}]',false,false,'verification_required'),
('paydunya','TG','XOF','PayDunya','[{"code":"t-money-togo","label":"Mixx by Yas / T-Money"},{"code":"moov-togo","label":"Moov Money / Flooz"},{"code":"card","label":"Carte bancaire"}]',false,true,'not_configured'),
('fedapay','TG','XOF','FedaPay','[{"code":"mobile_money","label":"Mobile Money"},{"code":"card","label":"Carte bancaire"}]',false,false,'not_configured'),
('cinetpay','TG','XOF','CinetPay','[{"code":"t-money","label":"T-Money"},{"code":"moov","label":"Moov Money"},{"code":"card","label":"Carte bancaire"}]',false,false,'not_configured')
on conflict(provider_code,country_code) do nothing;
create table if not exists public.payment_webhook_events (id uuid primary key default gen_random_uuid(),provider text not null,provider_event_id text not null,event_type text,payload_hash text,processing_status text not null default 'received' check(processing_status in ('received','processed','ignored','failed')),processed_at timestamptz,error_message text,received_at timestamptz not null default now(),unique(provider,provider_event_id));
create table if not exists public.supplier_conversations (id uuid primary key default gen_random_uuid(),supplier_contact_id uuid not null references public.supplier_contacts(id) on delete restrict,order_id uuid references public.orders(id) on delete set null,import_request_id uuid references public.import_requests(id) on delete set null,subject text not null,status text not null default 'open' check(status in ('open','waiting_supplier','waiting_admin','resolved','closed')),language text not null default 'en',ai_enabled boolean not null default true,assigned_admin_id uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists supplier_conversations_supplier_idx on public.supplier_conversations(supplier_contact_id,updated_at desc);
create table if not exists public.supplier_chat_messages (id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.supplier_conversations(id) on delete cascade,sender_type text not null check(sender_type in ('admin','supplier','ai','system')),sender_user_id uuid references auth.users(id) on delete set null,body text not null,language text,translated_body text,external_message_id text,channel text not null default 'internal' check(channel in ('internal','whatsapp','email','alibaba')),delivery_status text not null default 'internal' check(delivery_status in ('internal','queued','sent','delivered','read','failed','received')),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists supplier_chat_messages_conversation_idx on public.supplier_chat_messages(conversation_id,created_at);
create table if not exists public.fulfillment_jobs (id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,supplier_contact_id uuid references public.supplier_contacts(id) on delete set null,cargo_partner_id uuid references public.cargo_partners(id) on delete set null,stage text not null default 'awaiting_payment' check(stage in ('awaiting_payment','supplier_notification','supplier_confirmed','purchasing','quality_check','cargo_booking','in_transit','customs','last_mile','delivered','exception','cancelled')),supplier_payload jsonb not null default '{}'::jsonb,cargo_payload jsonb not null default '{}'::jsonb,idempotency_key text not null unique,last_error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists fulfillment_jobs_order_idx on public.fulfillment_jobs(order_id,created_at desc);
create index if not exists fulfillment_jobs_stage_idx on public.fulfillment_jobs(stage,updated_at);
create table if not exists public.fulfillment_events (id uuid primary key default gen_random_uuid(),fulfillment_job_id uuid not null references public.fulfillment_jobs(id) on delete cascade,event_type text not null,actor_type text not null default 'system' check(actor_type in ('system','admin','supplier','cargo','customer','ai')),description text not null,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists fulfillment_events_job_idx on public.fulfillment_events(fulfillment_job_id,created_at);
alter table public.store_members enable row level security;
alter table public.store_settings enable row level security;
alter table public.wallet_accounts enable row level security;
alter table public.wallet_transactions enable row level security;
alter table public.payout_requests enable row level security;
alter table public.payment_provider_configs enable row level security;
alter table public.payment_webhook_events enable row level security;
alter table public.supplier_conversations enable row level security;
alter table public.supplier_chat_messages enable row level security;
alter table public.fulfillment_jobs enable row level security;
alter table public.fulfillment_events enable row level security;
create policy "store members read own membership or admin" on public.store_members for select to authenticated using(user_id=auth.uid() or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create policy "store owner manages members" on public.store_members for all to authenticated using(exists(select 1 from public.stores s where s.id=store_id and s.owner_id=auth.uid()) or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check(exists(select 1 from public.stores s where s.id=store_id and s.owner_id=auth.uid()) or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create policy "store settings owner read" on public.store_settings for select to authenticated using(exists(select 1 from public.stores s where s.id=store_id and s.owner_id=auth.uid()) or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create policy "store settings owner update" on public.store_settings for all to authenticated using(exists(select 1 from public.stores s where s.id=store_id and s.owner_id=auth.uid()) or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check(exists(select 1 from public.stores s where s.id=store_id and s.owner_id=auth.uid()) or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create policy "wallet owner reads own" on public.wallet_accounts for select to authenticated using(owner_user_id=auth.uid() or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create policy "wallet transaction owner reads own" on public.wallet_transactions for select to authenticated using(exists(select 1 from public.wallet_accounts w where w.id=wallet_account_id and w.owner_user_id=auth.uid()) or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create policy "payout owner reads own" on public.payout_requests for select to authenticated using(user_id=auth.uid() or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create policy "payout owner requests own" on public.payout_requests for insert to authenticated with check(user_id=auth.uid() and status='requested' and exists(select 1 from public.wallet_accounts w where w.id=wallet_account_id and w.owner_user_id=auth.uid() and w.status='active'));
create policy "admin manages payouts" on public.payout_requests for update to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create policy "provider config visible" on public.payment_provider_configs for select to authenticated using(true);
create policy "admin manages provider config" on public.payment_provider_configs for all to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create policy "admin reads webhook events" on public.payment_webhook_events for select to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create policy "admin manages supplier conversations" on public.supplier_conversations for all to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create policy "admin manages supplier chat messages" on public.supplier_chat_messages for all to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create policy "admin manages fulfillment jobs" on public.fulfillment_jobs for all to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create policy "admin reads fulfillment events" on public.fulfillment_events for select to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
